from dataclasses import dataclass


@dataclass(frozen=True)
class Const:
    n: int


@dataclass(frozen=True)
class Var:
    name: str


@dataclass(frozen=True)
class Add:
    a: "E"
    b: "E"


@dataclass(frozen=True)
class Mul:
    a: "E"
    b: "E"


E = Const | Var | Add | Mul


def to_string(e: E) -> str:
    """Used to print test results. Don't change it."""
    match e:
        case Const(n):
            return str(n)
        case Var(s):
            return s
        case Add(a, b):
            return f"({to_string(a)} + {to_string(b)})"
        case Mul(a, b):
            return f"({to_string(a)} * {to_string(b)})"


# Write a wrap32 helper here if you need it.


def simplify(e: E) -> E:
    """Simplify sources first (children before their parent),
    then re-apply the rules to each result until none fire."""
    return e
